// The phone-free schools bill, traced from seven filings to a conference room.
//
// Lifted whole from a prototype that had already done the hard parts. Three of
// them could not have been derived from the legislature's API:
//
//   The maps. 160 House and 40 Senate cells as ready polygons, plus the state
//   outline. They are Voronoi cells grown from one seed per seat, not real
//   district boundaries, so they show who voted rather than where: equal cells
//   for equal votes. Anything on this page that implies geography would be
//   overclaiming.
//
//   The stages. Nine steps with written headlines and bodies. The sequence is
//   recoverable from the history actions; the prose is not.
//
//   The provisions. Which ideas survived the merge, which originating bill each
//   traces to, and whether that link is `documented` or `inferred` with the
//   reasoning attached. This is judgement work and it is labelled as such,
//   which is the part worth keeping whatever else changes.
//
// Everything else here (roll calls, the seven origin bills, the 200 members,
// the conferees, the floor amendments) does exist in the API, and could be
// re-derived if this ever needs to run for a bill other than S.2581.
//
// Keys are the prototype's own: "S:Crighton" for a senator, "Middlesex-24" for
// a House seat, because the vote maps index by them.

export interface Stage {
  id: string;
  label: string;
  date: string;
  chamber: "Senate" | "House" | "Conference";
  head: string;
  body: string;
}

export interface RollCall {
  /** "S" or "H". */
  ch: string;
  label: string;
  tally: string;
  date: string;
  /** Member or seat key to "Y" or "N". Absent members are simply missing. */
  votes: Record<string, string>;
}

export interface Provision {
  /** The provision, in plain words. */
  t: string;
  /** "kept" or "changed", against the originating bills. */
  s: string;
  /** Which of the seven filings it traces to, where that is knowable. */
  from: string[];
  /** "documented" or "inferred": how solid the trace is. */
  conf: string;
  /** Why the trace was drawn that way. */
  why: string;
}

export interface Origin {
  num: string;
  title: string;
  sponsor: string;
  district: string;
  note: string;
  key: string;
}

export interface Seat {
  n: string;
  p: string;
  d: string;
  /** "H" or "S". */
  c: string;
  s: string[];
  ch: string[];
}

export interface Conferee {
  n: string;
  d: string;
  ch: string;
  p: string;
  chair: boolean;
  key: string;
}

export interface Geo {
  /** The state, as SVG path data. Three pieces: mainland and two islands. */
  outline: string[];
  /** One point per seat, the centre each cell was grown from. */
  seeds: Record<string, [number, number]>;
  /** Seat key to polygon points, "x,y x,y …". */
  house: Record<string, string[]>;
  senate: Record<string, string[]>;
  /** minX, minY, width, height. */
  box: [number, number, number, number];
}

export interface BillLineage {
  votes: Record<string, RollCall>;
  amend: { n: string; num: string; disp: string; key: string }[];
  geo: Geo;
  seats: Record<string, Seat>;
  origins: Origin[];
  conf: Conferee[];
  chairs: unknown[];
  stages: Stage[];
  provisions: Provision[];
}

